import { expect, test } from './fixtures';

/**
 * Design conformance, in a real browser.
 *
 * Generated by design-tools/gen-conformance.mjs from the design handoff, and
 * checked in deliberately. These assert the frame and the measurements — the
 * part visual review reliably misses. The numbers are hand-set in the mock and
 * do not round to a spacing ladder, so a later pass that tidies them would
 * silently redraw the screen. That is what this is here to stop; it is not
 * pedantry.
 *
 * Source: doc/handoffs/kinds-band/Tablet.dc.html (the KIND band, c436)
 * Extracted at 2026-11-05T01:50:40.018Z at 800x1280.
 *
 * Regenerating overwrites this file. Hand edits belong in a sibling spec.
 */

const base = process.env.PLAYWRIGHT_BASE_URL ?? '';

// Kept by hand over the generator's output (c436): the KIND band as Board 3A
// draws it, tablet portrait, 800x1280, which is the `tablet-portrait`
// project's own viewport. It runs in every device project (its name matches
// no DEVICE_IGNORE line, which is e2e's), so it pins the viewport and skips
// itself elsewhere; the band on every device is library-top-scroll's.
test.use({ viewport: { width: 800, height: 1280 } });
test.beforeEach(() => {
	test.skip(test.info().project.name !== 'tablet-portrait', 'drawn at tablet portrait');
});

const SEL = {
	band: '.kinds',
	kindLabel: '.kinds .klabel',
	kindCell: '.kinds .kc:nth-child(2)',
	kindCount: '.kinds .kc:nth-child(2) .n',
	filterCell: '.kinds .kfilter summary'
};

test('screen: band matches the handoff', async ({ page }) => {
	await page.goto(`${base}/?shelf=all&sort=title`);
	await expect(page.locator(SEL.band)).toBeVisible();

	const bandStyle = await page.locator(SEL.band).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display,
			borderBottomWidth: cs.borderBottomWidth
		};
	});
	expect(bandStyle.display).toBe('flex');
	expect(bandStyle.borderBottomWidth).toBe('1px');
});

test('screen: kindLabel matches the handoff', async ({ page }) => {
	await page.goto(`${base}/?shelf=all&sort=title`);
	await expect(page.locator(SEL.kindLabel)).toBeVisible();

	const kindLabelStyle = await page.locator(SEL.kindLabel).evaluate((node) => {
		const cs = getComputedStyle(node);
		return {
			display: cs.display,
			alignItems: cs.alignItems,
			paddingRight: cs.paddingRight,
			paddingLeft: cs.paddingLeft,
			borderRightWidth: cs.borderRightWidth,
			fontSize: cs.fontSize,
			fontWeight: cs.fontWeight,
			letterSpacing: cs.letterSpacing,
			lineHeight: cs.lineHeight
		};
	});
	expect(kindLabelStyle.display).toBe('flex');
	expect(kindLabelStyle.alignItems).toBe('center');
	expect(kindLabelStyle.paddingRight).toBe('14px');
	expect(kindLabelStyle.paddingLeft).toBe('24px');
	expect(kindLabelStyle.borderRightWidth).toBe('1px');
	expect(kindLabelStyle.fontSize).toBe('12px');
	expect(kindLabelStyle.fontWeight).toBe('500');
	expect(kindLabelStyle.letterSpacing).toBe('0.72px');
	expect(kindLabelStyle.lineHeight).toBe('12px');
});

